import { BadRequestException } from '@nestjs/common';

export const PROFILE_PHOTO_MAX_FILE_SIZE_BYTES = 5 * 1024 * 1024;
export const PROFILE_PHOTO_ALLOWED_MIME_TYPES = new Set([
  'image/png',
  'image/jpeg',
  'image/webp',
]);
export const PROFILE_AVATAR_IDS = new Set(
  Array.from({ length: 12 }, (_, index) => index + 1),
);

export type ProfilePhotoImageFormat = 'png' | 'jpeg' | 'webp';

export interface ProfilePhotoUpload {
  buffer: Buffer;
  mimetype: string;
  size: number;
}

export function profilePhotoFileFilter(
  _request: { ip?: string },
  file: { mimetype: string },
  callback: (error: Error | null, acceptFile: boolean) => void,
): void {
  if (!PROFILE_PHOTO_ALLOWED_MIME_TYPES.has(file.mimetype.toLowerCase())) {
    callback(
      new BadRequestException({
        code: 'unsupported_profile_photo',
        message: 'Only PNG, JPEG, and WebP profile photos are allowed.',
      }),
      false,
    );
    return;
  }
  callback(null, true);
}

export function detectProfilePhotoImageFormat(
  buffer: Buffer,
): ProfilePhotoImageFormat | undefined {
  const isPng =
    buffer.length >= 8 &&
    buffer.subarray(0, 8).equals(
      Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    );
  if (isPng) return 'png';

  if (
    buffer.length >= 3 &&
    buffer[0] === 0xff &&
    buffer[1] === 0xd8 &&
    buffer[2] === 0xff
  ) {
    return 'jpeg';
  }

  if (
    buffer.length >= 12 &&
    buffer.subarray(0, 4).toString('ascii') === 'RIFF' &&
    buffer.subarray(8, 12).toString('ascii') === 'WEBP'
  ) {
    return 'webp';
  }

  return undefined;
}

export function validateProfilePhotoUpload(
  file: ProfilePhotoUpload,
): ProfilePhotoImageFormat {
  if (
    !file ||
    !Buffer.isBuffer(file.buffer) ||
    file.size > PROFILE_PHOTO_MAX_FILE_SIZE_BYTES ||
    file.buffer.length > PROFILE_PHOTO_MAX_FILE_SIZE_BYTES
  ) {
    throw new BadRequestException({
      code: 'profile_photo_too_large',
      message: 'Profile photos must be 5 MB or smaller.',
    });
  }

  const mimeType = file.mimetype.toLowerCase();
  if (!PROFILE_PHOTO_ALLOWED_MIME_TYPES.has(mimeType)) {
    throw new BadRequestException({
      code: 'unsupported_profile_photo',
      message: 'Only PNG, JPEG, and WebP profile photos are allowed.',
    });
  }

  const format = detectProfilePhotoImageFormat(file.buffer);
  const expectedMimeType = format === 'jpeg' ? 'image/jpeg' : format ? `image/${format}` : '';
  if (!format || expectedMimeType !== mimeType) {
    throw new BadRequestException({
      code: 'invalid_profile_photo',
      message: 'The profile photo content does not match its declared image type.',
    });
  }

  return format;
}

export function createSafeProfilePhotoFilename(
  format: ProfilePhotoImageFormat,
  randomName: string,
): string {
  const extension = format === 'jpeg' ? 'jpg' : format;
  return `${randomName}.${extension}`;
}
